def solution():
    N = 8
    P = [26, 23, 23, 30, 18, 1, 25, 9]
    dp = [0] * (N + 1)
    for i in range(1, N + 1):
        max_val = 0
        for j in range(1, i + 1):
            if j == i:
                val = P[i - 1]
            else:
                val = P[j - 1] + dp[i - j]
            max_val = max(max_val, val)
