def solution() -> int:
    weights = [9, 5]
    total = sum(weights)
    min_diff = float('inf')
    # Generate all subsets using bit manipulation (2^n possibilities)
    for i in range(1 << len(weights)):
        s1 = 0
        for j in range(len(weights)):
            if i & (1 << j):
                s1 += weights[j]
        s2 = total - s1
        diff = abs(s1 - s2)
        if diff < min_diff:
            min_diff = diff
    return min_diff

