def solution():
    import heapq
    from collections import defaultdict

    # Define edges (assuming undirected graph, adding both directions)
    edges = [(4, 0, 1), (1, 0, 7), (2, 3, 7), (3, 4, 6), (4, 1, 2), (2, 4, 3)]
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Dijkstra's algorithm
    dist = {node: float('inf') for node in range(5)}
    dist[0] = 0
    parent = {0: None}
    pq = [(0, 0)]  # (distance, node)

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                parent[v] = u
                heapq.heappush(pq, (dist[v], v))

    # Reconstruct path
    if dist[4] == float('inf'):
        return [], -1
    path = []
    current = 4
    while current is not None:
        path.append(current)
        current = parent.get(current)
    path.reverse()
    return path, dist[4]

