    import heapq
    from typing import Dict, List, Tuple

    graph: Dict[int, Dict[int, int]] = {
        0: {4: 1},
        1: {0: 1, 3: 7},
        2: {1: 7},
        3: {0: 1, 4: 6},
        4: {}
    }

    start = 0
    target = 4

    distances: Dict[int, float] = {node: float('inf') for node in graph}
    distances[start] = 0
    pq: List[Tuple[float, int]] = [(0, start)]
    previous: Dict[int, int] = {node: None for node in graph}

    while pq:
        dist, node = heapq.heappop(pq)
        if node == target:
            break
        if dist > distances[node]:
            continue
        for neighbor, weight in graph[node].items():
            alt = dist + weight
            if alt < distances[neighbor]:
                distances[neighbor] = alt
                previous[neighbor] = node
                heapq.heappush(pq, (alt, neighbor))

    # Reconstruct path
    path: List[int] = []
    current = target
    while current is not None:
        path.append(current)
        current = previous[current]
    path.reverse()

    if path[0] != start:
        return [], -1  # No path found, though one exists here

    return path, int(distances[target])

