def solution() -> Tuple[List[int], int]:
    import heapq
    from collections import defaultdict

    # Define the graph as undirected adjacency list
    graph = defaultdict(list)
    edges = [
        (0, 1, 3),
        (4, 3, 6),
        (3, 1, 5),
        (4, 0, 7),
        (5, 2, 8),
        (5, 0, 1),
        (5, 4, 5)
    ]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Dijkstra's algorithm to find shortest path from 0 to 5
    def dijkstra(start, end):
        queue = [(0, start, [])]  # (distance, node, path)
        distances = {node: float('inf') for node in range(6)}
        distances[start] = 0
        visited = set()

        while queue:
            dist, node, path = heapq.heappop(queue)
            if node in visited:
                continue
            visited.add(node)
            current_path = path + [node]
            if node == end:
                return current_path, dist
            for neighbor, weight in graph[node]:
                if dist + weight < distances[neighbor]:
                    distances[neighbor] = dist + weight
                    heapq.heappush(queue, (dist + weight, neighbor, current_path))
        return None, float('inf')

    path, distance = dijkstra(0, 5)
    return path, int(distance)

