code_question:
def solution() -> tuple[bool, int, list[int]]:
    weights = [5, 3, 4, 2, 4]
    values = [1, 5, 1, 5, 2]
    capacity = 25
    n = len(weights)
    # Dynamic programming table: dp[i][w] is max value with first i items and capacity w
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]
    total_value = dp[n][capacity]
    # Backtrack to find selected items
    selected = []
    w = capacity
    for i in range(n, 0, -1):
        if dp[i][w] != dp[i - 1][w]:
            selected.append(i - 1)
            w -= weights[i - 1]
    selected.sort()
    return True, total_value, selected

