def solution() -> Dict[int, str]:
    import pulp

    prob = pulp.LpProblem("GraphColoring", pulp.LpMinimize)

    vertices = list(range(1, 7))
    colors = ['A', 'B']
    edges = [(1, 2), (1, 3), (1, 4), (2, 5), (4, 5), (4, 6)]

    x = pulp.LpVariable.dicts("x", (vertices, colors), cat='Binary')

    for i in vertices:
        prob += pulp.lpSum(x[i][c] for c in colors) == 1

    for i, j in edges:
        for c in colors:
            prob += x[i][c] + x[j][c] <= 1

    prob.solve(pulp.PULP_CBC_CMD(msg=False))

    assignment = {}
    for i in vertices:
        for c in colors:
            if pulp.value(x[i][c]) == 1:
                assignment[i] = c

    return assignment

