    from collections import deque
    color = {}
    for vertex in graph:
        if vertex not in color:
            # Start BFS from this vertex, assign color A
            queue = deque([vertex])
            color[vertex] = 'A'
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if v not in color:
                        # Alternate color
