from pulp import LpProblem, LpVariable, LpMinimize, lpSum, LpBinary, LpStatus

def solution() -> dict[int, str]:
    # Define vertices and edges
    vertices = [1, 2, 3, 4, 5, 6, 7, 8]
    edges = [(1,7), (1,8), (2,3), (2,4), (3,5), (3,6), (4,8), (5,6)]
    colors = ['A', 'B', 'C']

    # Create LP problem
    prob = LpProblem("Graph_Coloring", LpMinimize)

    # Variables: x[i][c] = 1 if vertex i has color c
    x = {(i, c): LpVariable(f"x_{i}_{c}", cat=LpBinary) for i in vertices for c in colors}

    # Objective: minimize sum (dummy, since we just need feasibility)
    prob += lpSum(x[i, c] for i in vertices for c in colors)

    # Constraints: each vertex has exactly one color
    for i in vertices:
        prob += lpSum(x[i, c] for c in colors) == 1

    # No two adjacent vertices have the same color
    for (i, j) in edges:
        for c in colors:
            prob += x[i, c] + x[j, c] <= 1

    # Solve
    prob.solve()

    # Extract solution
    coloring = {}
    for i in vertices:
        for c in colors:
            if x[i, c].varValue == 1:
                coloring[i] = c
                break

    return coloring

